import numpy as np
def equation(t, P, params):
    a,b,k,w,m,d,e,f,h,n = params[0],params[1],params[2],params[3],params[4],params[5],params[6],params[7],params[8],params[9]
    s = np.sin(w*t); c = np.cos(w*t)
    return (a + b*s + k*c)*P + m*np.sqrt(P) + d*t + e + f*s + h*np.cos(2*w*t) + n*np.sin(2*w*t)
